def sparseDot(idxA, valA, idxB, valB):
    i = j = 0
    total = 0
    while i < len(idxA) and j < len(idxB):
        if idxA[i] == idxB[j]:
            total += valA[i] * valB[j]
            i += 1
            j += 1
        elif idxA[i] < idxB[j]:
            i += 1
        else:
            j += 1
    return total
